  function chat(p){return (p.messages||[]).map(m=>`<div class="chat-line"><span class="avatar ${m.who==='mokina'?'mokina':''}">${m.who==='mokina'?brandMark('white'):'你'}</span><div><div class="chat-meta">${m.who==='mokina'?'Mokina':'你'} <time>${esc(m.time)}</time></div><div class="chat-bubble">${esc(m.text)}</div></div></div>`).join('');}
  function versionDoc(p,versionId){
    if(p.versionContent?.[versionId])return p.versionContent[versionId];
    const doc=structuredClone(sample[p.kind]||sample.plan);
    if(versionId&&versionId!==p.current){
      doc.lead=`${doc.lead}（${versionId} 历史示例；内容按该版本冻结。）`;
      if(doc.sections[0])doc.sections[0].body+=' 这一版尚未包含后续修订的章节说明。';
    }
    return doc;
  }
  function documentSections(doc){return doc.sections.map(s=>`<section data-od-id="document-${esc(s.id)}"><h2>${esc(s.title)}</h2><p>${esc(s.body)}</p>${s.table?`<div class="table-scroll"><table><thead><tr>${s.table[0].map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${s.table.slice(1).map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</section>`).join('');}
  function candidateDocument(p){
    const c=p.candidate;if(!c)return null;
    if(c.document)return structuredClone(c.document);
    const doc=structuredClone(versionDoc(p,c.base));const section=doc.sections.find(s=>s.id===c.chapter);
    if(section)section.body=c.text||section.body;
    return doc;
  }
