  document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.workspace-options[open]').forEach(el=>{el.open=false;el.querySelector('summary')?.focus();});if(state.dialog){closeDialog();}else if(state.demoOpen){set({demoOpen:false});}else if(state.homeMore){closeHomeMore();}}if(state.dialog&&e.key==='Tab'){const focus=[...document.querySelectorAll('#overlay-root button:not([disabled]),#overlay-root [tabindex="0"]')];if(!focus.length)return;const first=focus[0],last=focus[focus.length-1];if(!focus.includes(document.activeElement)){e.preventDefault();(e.shiftKey?last:first).focus();}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}if(e.target.classList?.contains('resize-handle')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();state.collabWidth=Math.max(316,Math.min(470,state.collabWidth+(e.key==='ArrowRight'?16:-16)));save();render();document.querySelector('.resize-handle')?.focus();}});
